// Weekly operations briefing, generated by Claude from the dashboard's own data.
// Gathers this-week-vs-last-week numbers, asks Claude to write a short plain-English
// briefing, and caches the result in ai_briefings (one per week) so the page load is
// instant and the API is only called when an admin generates/refreshes.
const db = require("../db/db");
const m = require("./metrics");
const ai = require("./ai");

const shortName = (n) => (n || "").replace(/Futuro Childcare (and|&) Education\s*-?\s*/i, "").replace(/^Futuro\s+/, "").trim();
const daysBack = (dateStr, n) => { const d = new Date(dateStr + "T00:00:00Z"); d.setUTCDate(d.getUTCDate() - n); return d.toISOString().slice(0, 10); };

// Assemble the compact data packet the briefing is written from.
function gatherWeekData() {
  const to = m.defaultRange().to;                 // latest data date = week-ending anchor
  const from = daysBack(to, 6);                   // this week: 7 days
  const lastTo = daysBack(to, 7), lastFrom = daysBack(to, 13); // prior week

  const thisRows = m.overview(from, to);
  const lastRows = m.overview(lastFrom, lastTo);
  const lastBy = {}; lastRows.forEach((r) => { lastBy[r.owna_id] = r; });

  const centres = thisRows.map((r) => {
    const p = lastBy[r.owna_id] || {};
    return {
      centre: shortName(r.name),
      occupancy_pct: r.occupancy,
      occupancy_pct_prev: p.occupancy != null ? p.occupancy : null,
      attendance_pct: r.attendance_rate,
      revenue: r.fee_total,
      revenue_prev: p.fee_total != null ? p.fee_total : null,
      enrolled: r.enrolled,
      capacity: r.capacity,
    };
  });

  const t = m.totals(thisRows), tl = m.totals(lastRows);
  const pc = m.pcGroupLatest() || {};
  return {
    week_from: from, week_to: to,
    group: {
      occupancy_pct: t.occupancy, occupancy_pct_prev: tl.occupancy,
      attendance_pct: t.attendance_rate,
      revenue: t.fee_total, revenue_prev: tl.fee_total,
      enrolled: t.enrolled, capacity: t.capacity,
    },
    people: { turnover_yoy_pct: pc.turnover, enps: pc.enps, family_nps: pc.family_nps, as_of: pc.month },
    centres,
  };
}

function buildPrompt(data) {
  const system = [
    "You are the operations analyst for Futuro, an Australian early-learning (childcare) group.",
    "You write a concise weekly operations briefing for the leadership team from the supplied data.",
    "Be specific and use the numbers. Compare this week to last week where prior figures are given.",
    "Occupancy and attendance are percentages; revenue is in AUD; turnover is a rolling 12-month rate (lower is better).",
    "Never invent data that isn't provided. If prior-week figures are null, don't fabricate a trend.",
    "Format as short Markdown: a one-line **Headline**, then **What moved** (3-5 bullets, name centres), then **Watch list** (1-3 bullets). Keep it under ~200 words. Australian spelling.",
  ].join(" ");
  const user = "Here is this week's operations data as JSON:\n\n```json\n" + JSON.stringify(data, null, 2) + "\n```\n\nWrite the weekly briefing.";
  return { system, user };
}

async function generateBriefing() {
  const data = gatherWeekData();
  const { system, user } = buildPrompt(data);
  const content = await ai.complete({ system, user, maxTokens: 900 });
  db.prepare(`INSERT INTO ai_briefings (period_to, period_from, content, model, created_at)
    VALUES (@to,@from,@content,@model,datetime('now'))
    ON CONFLICT(period_to) DO UPDATE SET period_from=@from, content=@content, model=@model, created_at=datetime('now')`)
    .run({ to: data.week_to, from: data.week_from, content, model: ai.MODEL });
  return getLatest();
}

function getLatest() {
  return db.prepare("SELECT * FROM ai_briefings ORDER BY period_to DESC LIMIT 1").get() || null;
}
// Is the newest briefing for the current data week?
function isCurrent(b) { return !!b && b.period_to === m.defaultRange().to; }

module.exports = { gatherWeekData, buildPrompt, generateBriefing, getLatest, isCurrent };
